const d = $('New Appointment Webhook').first().json;
const date = new Date(`${d.date}T${d.time}`).toLocaleDateString('en-MY', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const time = new Date(`${d.date}T${d.time}`).toLocaleTimeString('en-MY', { hour: '2-digit', minute: '2-digit' });
const greeting = d.contactName ? `Hi ${d.contactName},` : 'Hello,';

const message = [
  greeting,
  ``,
  `📅 New appointment has been scheduled:`,
  ``,
  `🏥 ${d.hospital}`,
  `🗓️ ${date}`,
  `🕐 ${time}`,
  d.notes ? `📝 ${d.notes}` : null,
  ``,
  `— KAI Caregiving App`
].filter(Boolean).join('\n');

return [{ json: { message, to: d.to } }];
